45:   public BatchOperationExecuteProcessor(
46:       final Writers writers,
47:       final ProcessingState processingState,
48:       final int partitionId,
49:       final Map<BatchOperationType, BatchOperationExecutor> handlers) {
50:     commandWriter = writers.command();
51:     stateWriter = writers.state();
