59:   public void processRecord(final TypedRecord<BatchOperationExecutionRecord> command) {
60:     final var executionRecord = command.getValue();
61:     LOGGER.debug(
62:         "Processing new command with key '{}' on partition{} : {}",
63:         command.getKey(),
64:         partitionId,
65:         executionRecord);
66:     final long batchKey = executionRecord.getBatchOperationKey();
67: 
68:     final var batchOperation = getBatchOperation(batchKey);
69:     if (batchOperation == null) {
70:       LOGGER.debug("No batch operation found for key '{}'.", batchKey);
71:       return;
72:     }
73: 
74:     if (batchOperation.isSuspended()) {
75:       LOGGER.info("Batch operation {} is paused.", batchOperation.getKey());
76:       return;
77:     }
78: 
79:     final var entityKeys = batchOperationState.getNextItemKeys(batchKey, BATCH_SIZE);
80:     if (entityKeys.isEmpty()) {
81:       LOGGER.debug(
82:           "No items to process for BatchOperation {} on partition {}", batchKey, partitionId);
83: 
84:       appendBatchOperationExecutionExecutedEvent(command.getValue(), Collections.emptySet());
85:       appendBatchOperationExecutionCompletedEvent(command.getValue());
86:       return;
87:     }
88: 
89:     appendBatchOperationExecutionExecutingEvent(command.getValue(), Set.copyOf(entityKeys));
90: 
91:     final var handler = handlers.get(batchOperation.getBatchOperationType());
92:     entityKeys.forEach(entityKey -> handler.execute(entityKey, batchOperation));
93: 
94:     appendBatchOperationExecutionExecutedEvent(command.getValue(), Set.copyOf(entityKeys));
