96:     LOGGER.debug(
97:         "Scheduling next batch for BatchOperation {} on partition {}", batchKey, partitionId);
98:     final var followupCommand = new BatchOperationExecutionRecord();
99:     followupCommand.setBatchOperationKey(batchKey);
