75:   private void scheduleExecution() {
76:     if (!executing.get()) {
77:       processingContext
78:           .getScheduleService()
79:           .runDelayedAsync(pollingInterval, this::execute, AsyncTaskGroup.BATCH_OPERATIONS);
80:     } else {
81:       LOG.warn("Execution is already in progress, skipping scheduling.");
82:     }
83:   }
