86:     try {
87:       LOG.trace("Looking for pending batch operations to execute (scheduled).");
88:       executing.set(true);
89:       batchOperationState.foreachPendingBatchOperation(
90:           bo -> executeBatchOperation(bo, taskResultBuilder));
91:       return taskResultBuilder.build();
92:     } finally {
93:       executing.set(false);
94:       scheduleExecution();
95:     }
96:   }
