100:     if (batchOperation.isSuspended()) {
101:       LOG.trace("Batch operation {} is paused.", batchOperation.getKey());
102:       return;
103:     }
104: 
105:     // First fire a start event
106:     appendStartedCommand(taskResultBuilder, batchOperation);
107: 
108:     try {
109:       // Then append the chunks
110:       final var keys = queryAllKeys(batchOperation);
111:       for (int i = 0; i < keys.size(); i += chunkSize) {
112:         final Set<Item> chunkKeys =
113:             keys.stream().skip(i).limit(chunkSize).collect(Collectors.toSet());
114:         appendChunk(batchOperation.getKey(), taskResultBuilder, chunkKeys);
115:       }
116: 
117:       appendExecution(batchOperation.getKey(), taskResultBuilder);
118:     } catch (final Exception e) {
119:       LOG.error(
120:           "Failed to append chunks for batch operation with key {}. It will be removed from queue",
