131:     command.setBatchOperationKey(batchOperationKey);
132:     command.setBatchOperationType(batchOperation.getBatchOperationType());
133:     LOG.debug("Appending batch operation {} started event", batchOperationKey);
134:     taskResultBuilder.appendCommandRecord(batchOperationKey, BatchOperationIntent.START, command);
135:   }
