188:                   .parentProcessInstanceKeyOperations(Operation.exists(false))
189:                   .build(),
190:               batchOperation.getAuthentication(),
191:               abortCondition);
192:       case MIGRATE_PROCESS_INSTANCE, MODIFY_PROCESS_INSTANCE ->
