405:       final String documentId,
406:       final String storeId,
407:       final Part file,
408:       final DocumentMetadata metadata) {
409:     final InputStream inputStream;
410:     try {
411:       inputStream = file.getInputStream();
412:     } catch (final IOException e) {
413:       return Either.left(createInternalErrorProblemDetail(e, "Failed to read document content"));
414:     }
415:     final var validationResponse = validateDocumentMetadata(metadata);
416:     final var internalMetadata = toInternalDocumentMetadata(metadata, file);
