612:   public static Authentication getAuthentication() {
613:     final Map<String, Object> claims = new HashMap<>();
614:     final var authenticationBuilder = new Builder();
615: 
616:     final var requestAuthentication = SecurityContextHolder.getContext().getAuthentication();
617:     if (requestAuthentication != null) {
618:       if (requestAuthentication.getPrincipal()
619:           instanceof final CamundaPrincipal authenticatedPrincipal) {
620:         final var authenticationContext = authenticatedPrincipal.getAuthenticationContext();
621: 
622:         authenticationBuilder.roleIds(
623:             authenticationContext.roles().stream().map(RoleEntity::roleId).toList());
624: 
625:         authenticationBuilder.tenants(
626:             authenticationContext.tenants().stream().map(TenantDTO::tenantId).toList());
627: 
628:         authenticationBuilder.groupIds(authenticationContext.groups());
629: 
630:         if (authenticationContext.username() != null) {
631:           final var authenticatedUsername = authenticationContext.username();
632:           claims.put(Authorization.AUTHORIZED_USERNAME, authenticatedUsername);
633:           authenticationBuilder.user(authenticatedUsername);
634:         } else {
635:           final var authenticatedClientId = authenticationContext.clientId();
636:           claims.put(Authorization.AUTHORIZED_CLIENT_ID, authenticatedClientId);
637:           authenticationBuilder.clientId(authenticatedClientId);
638:         }
639: 
640:         if (authenticatedPrincipal instanceof final CamundaOAuthPrincipal principal) {
641:           principal
642:               .getClaims()
643:               .forEach((key, value) -> ClaimTransformer.applyUserClaim(claims, key, value));
644:           authenticationBuilder.mapping(principal.getOAuthContext().mappingIds().stream().toList());
645:         }
646: 
647:         authenticationBuilder.claims(claims);
648:       }
649:     }
650: 
651:     return authenticationBuilder.build();
652:   }
