252:    *    .activateElement("element1")
253:    *    .and()
254:    *    .activateElement("element2")
255:    *    .withVariables(globalScopedVariables)
256:    *    .withVariables(localScopedVariables, "element2")
257:    *    .and()
258:    *    .terminateElement("element3")
259:    *    .send();
