267:   /**
268:    * Command to migrate a process instance to a different process definition.
269:    *
270:    * <p>The migration command contains a migration plan. Migration plan contains
271:    * targetProcessDefinitionKey to indicate which process definition to use for the migration.
272:    * Mapping instructions for the migration describe how to map elements from the source process
273:    * definition to the target process definition.
274:    *
275:    * <p>For example, let's consider we want to migrate process instance with key {@code 1}, target
276:    * process definition key {@code 2}, a source process definition with a service task with id
277:    * {@code "task1"} and the target process definition with a service task with id {@code "task2"}.
278:    * The migration command could be:
279:    *
280:    * <pre>{@code
281:    * {
282:    *  "processInstanceKey": 1,
283:    *  "migrationPlan": {
284:    *   "targetProcessDefinitionKey": 2,
285:    *   "mappingInstructions": [
286:    *    {
287:    *     "sourceElementId": "task1",
288:    *     "targetElementId": "task2"
289:    *    }
290:    *   ]
291:    *  }
292:    * }
293:    * }</pre>
294:    *
295:    * <pre>
296:    *
297:    * camundaClient
298:    *  .newMigrateProcessInstanceCommand(1L)
299:    *  .migrationPlan(2L)
300:    *  .addMappingInstruction("element1", "element2")
301:    *  .addMappingInstruction("element3", "element4")
302:    *  .send();
303:    * </pre>
304:    *
305:    * <pre>
306:    * final MigrationPlan migrationPlan =
307:    *         MigrationPlan.newBuilder()
308:    *             .withTargetProcessDefinitionKey(2L)
309:    *             .addMappingInstruction("element1", "element2")
310:    *             .addMappingInstruction("element3", "element4")
311:    *             .build();
312:    * camundaClient
313:    *  .newMigrateProcessInstanceCommand(1L)
314:    *  .migrationPlan(migrationPlan)
315:    *  .send();
316:    * </pre>
317:    *
318:    * @param processInstanceKey the key which refers to the process instance to migrate
319:    * @return a builder for the command
320:    */
321:   @ExperimentalApi("https://github.com/camunda/camunda/issues/14907")
322:   MigrateProcessInstanceCommandStep1 newMigrateProcessInstanceCommand(long processInstanceKey);
323: 
