109:   /** Adds an access token to the Authorization header of a gRPC call. */
110:   @Override
111:   public void applyCredentials(final CredentialsApplier applier) throws IOException {
112:     final CamundaClientCredentials camundaClientCredentials =
113:         credentialsCache.computeIfMissingOrInvalid(clientId, this::fetchCredentials);
114: 
115:     String type = camundaClientCredentials.getTokenType();
116:     if (type == null || type.isEmpty()) {
117:       throw new IOException(
118:           String.format("Expected valid token type but was absent or invalid '%s'", type));
119:     }
120: 
121:     type = Character.toUpperCase(type.charAt(0)) + type.substring(1);
122:     applier.put(
123:         HEADER_AUTH_KEY, String.format("%s %s", type, camundaClientCredentials.getAccessToken()));
124:   }
