126:   /**
127:    * Returns true if the request failed because it was unauthenticated or unauthorized, and a new
128:    * access token could be fetched; otherwise returns false.
129:    */
130:   @Override
131:   public boolean shouldRetryRequest(final StatusCode statusCode) {
132:     try {
133:       return statusCode.isUnauthorized()
134:           && credentialsCache
135:               .withCache(
136:                   clientId,
137:                   value -> {
138:                     final CamundaClientCredentials fetchedCredentials = fetchCredentials();
139:                     credentialsCache.put(clientId, fetchedCredentials).writeCache();
140:                     return !fetchedCredentials.equals(value) || !value.isValid();
141:                   })
142:               .orElse(false);
143:     } catch (final IOException e) {
144:       LOG.error("Failed while fetching credentials: ", e);
145:       return false;
146:     }
147:   }
