149:   private static String createParams(final OAuthCredentialsProviderBuilder builder) {
150:     final Map<String, String> payload = new HashMap<>();
151: 
152:     if (builder.sslConfigurationProvided()) {
153:       payload.put(
154:           "client_assertion",
155:           getClientAssertion(
156:               builder.getSslClientCertPath().toAbsolutePath().toString(),
157:               builder.getEntraCertificatePassword(),
158:               builder.getClientId(),
159:               builder.getAudience()));
160:       payload.put("client_assertion_type", JWT_ASSERTION_TYPE);
161:     } else {
162:       payload.put("client_secret", builder.getClientSecret());
163:     }
164: 
165:     payload.put("client_id", builder.getClientId());
166:     payload.put("audience", builder.getAudience());
167:     payload.put("grant_type", "client_credentials");
168:     final String scope = builder.getScope();
169:     if (scope != null) {
170:       payload.put("scope", scope);
171:     }
172: 
173:     return payload.entrySet().stream()
174:         .map(e -> encode(e.getKey()) + "=" + encode(e.getValue()))
175:         .collect(Collectors.joining("&"));
176:   }
177: 
178:   private static String encode(final String param) {
179:     try {
180:       return URLEncoder.encode(param, StandardCharsets.UTF_8.name());
181:     } catch (final UnsupportedEncodingException e) {
182:       throw new UncheckedIOException("Failed while encoding OAuth request parameters: ", e);
183:     }
184:   }
