186:   private CamundaClientCredentials fetchCredentials() throws IOException {
187:     final HttpURLConnection connection =
188:         (HttpURLConnection) authorizationServerUrl.openConnection();
189:     maybeConfigureCustomSSLContext(connection);
190:     connection.setRequestMethod("POST");
191:     connection.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");
192:     connection.setRequestProperty("Accept", "application/json");
193:     connection.setDoOutput(true);
194:     connection.setReadTimeout(toIntExact(readTimeout.toMillis()));
195:     connection.setConnectTimeout(toIntExact(connectionTimeout.toMillis()));
196:     connection.setRequestProperty("User-Agent", "camunda-client-java/" + VersionUtil.getVersion());
197: 
198:     try (final OutputStream os = connection.getOutputStream()) {
199:       final byte[] input = payload.getBytes(StandardCharsets.UTF_8);
200:       os.write(input, 0, input.length);
201:     }
202: 
203:     if (connection.getResponseCode() != 200) {
204:       throw new IOException(
205:           String.format(
206:               "Failed while requesting access token with status code %d and message %s.",
207:               connection.getResponseCode(), connection.getResponseMessage()));
208:     }
209: 
210:     try (final InputStream in = connection.getInputStream();
211:         final InputStreamReader reader = new InputStreamReader(in, StandardCharsets.UTF_8)) {
212:       final CamundaClientCredentials fetchedCredentials = CREDENTIALS_READER.readValue(reader);
213: 
214:       if (fetchedCredentials == null) {
215:         throw new IOException("Expected valid credentials but got null instead.");
216:       }
217: 
218:       return fetchedCredentials;
219:     }
220:   }
