222:   private void maybeConfigureCustomSSLContext(final HttpURLConnection connection) {
223:     if (connection instanceof HttpsURLConnection) {
224:       final HttpsURLConnection httpsConnection = (HttpsURLConnection) connection;
225:       httpsConnection.setSSLSocketFactory(createSSLContext());
226:     }
227:   }
