229:   private SSLSocketFactory createSSLContext() {
230:     if (keystorePath == null && truststorePath == null) {
231:       return SSLContexts.createSystemDefault().getSocketFactory();
232:     }
233:     final SSLContextBuilder builder = SSLContexts.custom();
234:     try {
235:       if (keystorePath != null) {
236:         builder.loadKeyMaterial(
237:             keystorePath,
238:             keystorePassword == null ? null : keystorePassword.toCharArray(),
239:             keystoreKeyPassword == null ? new char[0] : keystoreKeyPassword.toCharArray());
240:       }
241:       if (truststorePath != null) {
242:         builder.loadTrustMaterial(
243:             truststorePath, truststorePassword == null ? null : truststorePassword.toCharArray());
244:       }
245:       return builder.build().getSocketFactory();
246:     } catch (final NoSuchAlgorithmException
247:         | KeyManagementException
248:         | KeyStoreException
249:         | UnrecoverableKeyException
250:         | CertificateException
251:         | IOException e) {
252:       throw new RuntimeException("Failed to create SSL context", e);
253:     }
254:   }
