256:   private static String getClientAssertion(
257:       final String certPath, final String certStorePassword, final String clientId, final String audience) {
258:     final X509Certificate certificate;
259:     final Algorithm algorithm;
260:     try (final FileInputStream stream = new FileInputStream(certPath)) {
261:       final KeyStore keyStore = KeyStore.getInstance("PKCS12");
262:       final char[] password = certStorePassword.toCharArray();
263:       keyStore.load(stream, password);
264: 
265:       final String alias = keyStore.aliases().nextElement();
266:       final RSAPrivateKey privateKey = (RSAPrivateKey) keyStore.getKey(alias, password);
267:       final X509Certificate keyStoreCertificate = (X509Certificate) keyStore.getCertificate(alias);
268:       final RSAPublicKey publicKey = (RSAPublicKey) keyStoreCertificate.getPublicKey();
269: 
270:       certificate = (X509Certificate) keyStore.getCertificate(alias);
271:       algorithm = Algorithm.RSA256(publicKey, privateKey);
272:     } catch (final IOException | GeneralSecurityException e) {
273:       throw new RuntimeException("Failed to create client assertion", e);
274:     }
275: 
276:     final Date now = new Date();
277:     final String x5t = generateX5tThumbprint(certificate);
278: 
279:     final Map<String, Object> header = new HashMap<>();
280:     header.put("alg", "RSA256");
281:     header.put("typ", "JWT");
282:     header.put("x5t", x5t);
283: 
284:     return JWT.create()
285:         .withHeader(header)
286:         .withIssuer(clientId)
287:         .withSubject(clientId)
288:         .withAudience(audience)
289:         .withIssuedAt(now)
290:         .withNotBefore(now)
291:         .withExpiresAt(new Date(now.getTime() + 5 * 60 * 1000))
292:         .withJWTId(randomUUID().toString())
293:         .sign(algorithm);
294:   }
295: 
296:   private static String generateX5tThumbprint(final X509Certificate certificate) {
297:     try {
298:       final MessageDigest digest = MessageDigest.getInstance("SHA-1");
299:       final byte[] encoded = digest.digest(certificate.getEncoded());
300:       return Base64.getUrlEncoder().withoutPadding().encodeToString(encoded);
301:     } catch (final Exception e) {
302:       throw new RuntimeException("Failed to generate x5t thumbprint", e);
303:     }
304:   }
305: }
