477:                   .withHeader("User-Agent", matching("camunda-client-java/\\d+\\.\\d+\\.\\d+.*"))
478:                   .withRequestBody(
479:                       withAssertion ? matching(assertionRegex) : notMatching(assertionRegex))
480:                   .withRequestBody(
481:                       withAssertion
482:                           ? matching(assertionTypeRegex)
