422:   private void mockCredentials(final String token, final String scope) {
423:     final HashMap<String, String> map = new HashMap<>();
424:     map.put("client_secret", SECRET);
425:     map.put("client_id", CLIENT_ID);
426:     map.put("audience", AUDIENCE);
427:     map.put("grant_type", "client_credentials");
428:     if (scope != null) {
429:       map.put("scope", scope);
430:     }
431: 
432:     final String encodedBody =
433:         map.entrySet().stream()
434:             .map(e -> encode(e.getKey()) + "=" + encode(e.getValue()))
435:             .collect(Collectors.joining("&"));
436: 
437:     map.put("access_token", token);
438:     map.put("token_type", TOKEN_TYPE);
439:     map.put(
440:         "expires_in",
441:         String.valueOf(
442:             EXPIRY.getLong(ChronoField.INSTANT_SECONDS) - Instant.now().getEpochSecond()));
443: 
444:     try {
445:       final String body = jsonMapper.writeValueAsString(map);
446:       currentWiremockRuntimeInfo
447:           .getWireMock()
448:           .register(
449:               WireMock.post(WireMock.urlPathEqualTo("/oauth/token"))
450:                   .withHeader("Content-Type", equalTo("application/x-www-form-urlencoded"))
451:                   .withHeader("Accept", equalTo("application/json"))
452:                   .withHeader("User-Agent", matching("camunda-client-java/\\d+\\.\\d+\\.\\d+.*"))
453:                   .withRequestBody(equalTo(encodedBody))
454:                   .willReturn(
455:                       WireMock.aResponse().withBody(body).withFixedDelay(0).withStatus(200)));
456:     } catch (final JsonProcessingException e) {
457:       throw new RuntimeException(e);
458:     }
459:   }
