20: public final class UserTaskAssignedV2Applier
21:     implements TypedEventApplier<UserTaskIntent, UserTaskRecord> {
22: 
23:   private final MutableAsyncRequestState asyncRequestState;
24:   private final MutableElementInstanceState elementInstanceState;
25: 
26:   public UserTaskAssignedV2Applier(final MutableProcessingState processingState) {
27:     asyncRequestState = processingState.getUserTaskState();
28:     elementInstanceState = processingState.getElementInstanceState();
29:   }
30: 
31:   @Override
32:   public void applyState(final long key, final UserTaskRecord value) {
33:     final var userTaskRecord = new UserTaskRecord();
34:     userTaskRecord.wrapWithoutVariables(value);
35:     asyncRequestState.update(userTaskRecord.setChangedAttributes(List.of()).setAction(""));
36:     asyncRequestState.updateUserTaskLifecycleState(key, LifecycleState.CREATED);
37: 
38:     // Clear operational data related to the current assign(claim) transition
39:     asyncRequestState.deleteIntermediateState(key);
40:     asyncRequestState.deleteRecordRequestMetadata(key);
41:     asyncRequestState.deleteInitialAssignee(key);
42: 
43:     final var elementInstance = elementInstanceState.getInstance(value.getElementInstanceKey());
44:     if (elementInstance != null) {
45:       final long scopeKey = elementInstance.getValue().getFlowScopeKey();
46:       final var scopeInstance = elementInstanceState.getInstance(scopeKey);
47:       if (scopeInstance != null && scopeInstance.isActive()) {
48:         elementInstance.resetTaskListenerIndex(ZeebeTaskListenerEventType.assigning);
49:         elementInstanceState.updateInstance(elementInstance);
50:       }
51:     }
52:   }
53: }
