30: public class UserTaskCreateProcessor implements UserTaskCommandProcessor {
31: 
32:   private final ElementInstanceState elementInstanceState;
33:   private final ProcessState processState;
34:   private final AsyncRequestState userTaskState;
35:   private final StateWriter stateWriter;
36:   private final UserTaskCommandPreconditionChecker preconditionChecker;
37:   private final BpmnJobBehavior jobBehavior;
38:   private final BpmnUserTaskBehavior userTaskBehavior;
39: 
40:   public UserTaskCreateProcessor(
41:       final ProcessingState state,
42:       final Writers writers,
43:       final AuthorizationCheckBehavior authCheckBehavior,
44:       final BpmnUserTaskBehavior userTaskBehavior,
45:       final BpmnJobBehavior jobBehavior) {
46:     elementInstanceState = state.getElementInstanceState();
47:     processState = state.getProcessState();
48:     userTaskState = state.getUserTaskState();
49:     stateWriter = writers.state();
50:     preconditionChecker =
51:         new UserTaskCommandPreconditionChecker(
52:             List.of(LifecycleState.CREATING),
53:             "create",
54:             state.getUserTaskState(),
55:             authCheckBehavior);
56:     this.userTaskBehavior = userTaskBehavior;
57:     this.jobBehavior = jobBehavior;
58:   }
59: 
60:   @Override
61:   public Either<Rejection, UserTaskRecord> validateCommand(
62:       final TypedRecord<UserTaskRecord> command) {
