67:   public void onFinalizeCommand(
68:       final TypedRecord<UserTaskRecord> command, final UserTaskRecord userTaskRecord) {
69: 
70:     // Current assumption: there can not be corrections of the assignee if there is an initial
71:     // assignee.
72:     final long userTaskKey = command.getKey();
73:     userTaskState
74:         .findInitialAssignee(userTaskKey)
75:         .ifPresentOrElse(
76:             // if there is initial assignee -> remove the assignee from UT record as we are going
77:             // to assign user task to initial assignee via assigning event
78:             initialAssignee -> {
79:               final var valueWithoutAssignee = userTaskRecord.copy().unsetAssignee();
80:               stateWriter.appendFollowUpEvent(
81:                   userTaskKey, UserTaskIntent.CREATED, valueWithoutAssignee);
82: 
83:               // clean up the changed attributes because we have already finished the creation,
84:               // and are now starting a new transition to assigning
85:               valueWithoutAssignee.resetChangedAttributes();
86:               assignUserTask(valueWithoutAssignee, initialAssignee);
87:             },
88:             () ->
89:                 // if no initial assignee -> keep the assignee on the UT record in CREATED event
90:                 // it could be a corrected assignee or no assignee at all
91:                 stateWriter.appendFollowUpEvent(
92:                     userTaskKey, UserTaskIntent.CREATED, userTaskRecord));
93:   }
