96:     userTaskBehavior.userTaskAssigning(userTaskRecord, assignee);
97: 
98:     final var element =
99:         processState.getFlowElement(
100:             userTaskRecord.getProcessDefinitionKey(),
101:             userTaskRecord.getTenantId(),
102:             userTaskRecord.getElementIdBuffer(),
103:             ExecutableUserTask.class);
104: 
105:     final var elementInstance =
106:         elementInstanceState.getInstance(userTaskRecord.getElementInstanceKey());
