112:         .findFirst()
113:         .ifPresentOrElse(
114:             listener ->
115:                 jobBehavior.createNewTaskListenerJob(
116:                     context, userTaskRecord, listener, List.of(UserTaskRecord.ASSIGNEE)),
117:             () -> userTaskBehavior.userTaskAssigned(userTaskRecord, assignee));
118:   }
