76:   @Test
77:   public void shouldActivateUserTask() {
78:     // given
79:     ENGINE.deployment().withXmlResource(process()).deploy();
80: 
81:     // when
82:     final long processInstanceKey = ENGINE.processInstance().ofBpmnProcessId(PROCESS_ID).create();
83: 
84:     // then
85:     assertThat(
86:             RecordingExporter.processInstanceRecords()
87:                 .withProcessInstanceKey(processInstanceKey)
88:                 .withElementType(BpmnElementType.USER_TASK)
89:                 .withTenantId(TenantOwned.DEFAULT_TENANT_IDENTIFIER)
90:                 .limit(3))
91:         .extracting(Record::getRecordType, Record::getIntent)
92:         .containsSequence(
93:             tuple(RecordType.COMMAND, ProcessInstanceIntent.ACTIVATE_ELEMENT),
94:             tuple(RecordType.EVENT, ProcessInstanceIntent.ELEMENT_ACTIVATING),
95:             tuple(RecordType.EVENT, ProcessInstanceIntent.ELEMENT_ACTIVATED));
96: 
97:     final Record<ProcessInstanceRecordValue> userTask =
98:         RecordingExporter.processInstanceRecords()
99:             .withProcessInstanceKey(processInstanceKey)
100:             .withTenantId(TenantOwned.DEFAULT_TENANT_IDENTIFIER)
101:             .withIntent(ProcessInstanceIntent.ELEMENT_ACTIVATING)
102:             .withElementType(BpmnElementType.USER_TASK)
103:             .getFirst();
104: 
105:     Assertions.assertThat(userTask.getValue())
106:         .hasElementId("task")
107:         .hasBpmnElementType(BpmnElementType.USER_TASK)
108:         .hasFlowScopeKey(processInstanceKey)
109:         .hasBpmnProcessId(PROCESS_ID)
110:         .hasProcessInstanceKey(processInstanceKey);
111:   }
