159:         .hasProcessDefinitionKey(taskActivated.getValue().getProcessDefinitionKey())
160:         .hasBpmnProcessId(taskActivated.getValue().getBpmnProcessId())
161:         .hasProcessDefinitionVersion(taskActivated.getValue().getVersion());
162: 
163:     assertThat(userTask.getValue().getUserTaskKey()).isGreaterThan(0L);
164:   }
