328:   private <T extends UnifiedRecordValue> void requestContinuation(
329:       final String queue,
330:       final long key,
331:       final ValueType valueType,
332:       final Intent intent,
333:       final T value) {
334:     final var writeImmediately = !asyncRequestState.hasQueuedDistributions(queue);
335: 
336:     if (writeImmediately) {
337:       commandWriter.appendFollowUpCommand(key, intent, value);
338:       return;
339:     }
340: 
341:     commandDistributionContinuation.reset();
342:     commandDistributionContinuation.setQueueId(queue);
343:     commandDistributionContinuation.setPartitionId(currentPartitionId);
344:     commandDistributionContinuation.setValueType(valueType);
345:     commandDistributionContinuation.setIntent(intent);
346:     commandDistributionContinuation.setCommandValue(value);
347: 
348:     stateWriter.appendFollowUpEvent(
