364:   public void onAcknowledgeDistribution(
365:       final long distributionKey, final CommandDistributionRecord recordValue) {
366:     final var partitionId = recordValue.getPartitionId();
367: 
368:     // finish the distribution for the partition that acknowledged the distribution
369:     stateWriter.appendFollowUpEvent(
370:         distributionKey, CommandDistributionIntent.ACKNOWLEDGED, recordValue);
371: 
372:     getMetrics().removeInflightDistribution(partitionId);
373:     getMetrics().removePendingDistribution(partitionId);
374: 
375:     // Distribute next in queue if the distribution was part of a queue
376:     final var queueId = asyncRequestState.getQueueIdForDistribution(distributionKey);
377:     queueId.ifPresent(queue -> distributeNextInQueue(queue, partitionId));
378: 
379:     // Finish the distribution if there are no more pending distributions
380:     if (!asyncRequestState.hasPendingDistribution(distributionKey)) {
381:       final var finishRecord =
382:           new CommandDistributionRecord()
383:               .setPartitionId(currentPartitionId)
384:               .setValueType(recordValue.getValueType())
385:               .setIntent(recordValue.getIntent());
386:       queueId.ifPresent(finishRecord::setQueueId);
387: 
388:       commandWriter.appendFollowUpCommand(
389:           distributionKey, CommandDistributionIntent.FINISH, finishRecord);
390:     }
391:   }
