325:   private ZeebeTaskListenerEventType mapIntentToEventType(final UserTaskIntent intent) {
326:     return switch (intent) {
327:       case CREATE -> ZeebeTaskListenerEventType.creating;
328:       case ASSIGN, CLAIM -> ZeebeTaskListenerEventType.assigning;
329:       case UPDATE -> ZeebeTaskListenerEventType.updating;
330:       case COMPLETE -> ZeebeTaskListenerEventType.completing;
331:       case CANCEL -> ZeebeTaskListenerEventType.canceling;
332:       default ->
333:           throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(intent));
334:     };
335:   }
336: 
337:   private ZeebeTaskListenerEventType mapLifecycleStateToEventType(
338:       final LifecycleState lifecycleState) {
339:     return switch (lifecycleState) {
340:       case CREATING -> ZeebeTaskListenerEventType.creating;
341:       case ASSIGNING, CLAIMING -> ZeebeTaskListenerEventType.assigning;
342:       case UPDATING -> ZeebeTaskListenerEventType.updating;
343:       case COMPLETING -> ZeebeTaskListenerEventType.completing;
344:       case CANCELING -> ZeebeTaskListenerEventType.canceling;
345:       default ->
346:           throw new IllegalArgumentException(
347:               "Unexpected user task lifecycle state: '%s'".formatted(lifecycleState));
348:     };
349:   }
350: 
351:   private UserTaskIntent mapDeniedIntentToResponseIntent(final UserTaskIntent intent) {
352:     return switch (intent) {
353:       case COMPLETION_DENIED -> UserTaskIntent.COMPLETE;
354:       case ASSIGNMENT_DENIED -> UserTaskIntent.ASSIGN;
355:       case UPDATE_DENIED -> UserTaskIntent.UPDATE;
356:       default ->
357:           throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(intent));
358:     };
359:   }
360: 
361:   private String mapDeniedIntentToResponseRejectionReason(
362:       final UserTaskIntent intent, final long userTaskKey, final String deniedReason) {
363:     return switch (intent) {
364:       case COMPLETION_DENIED -> USER_TASK_COMPLETION_REJECTION.formatted(userTaskKey, deniedReason);
365:       case ASSIGNMENT_DENIED -> USER_TASK_ASSIGNMENT_REJECTION.formatted(userTaskKey, deniedReason);
366:       case UPDATE_DENIED -> USER_TASK_UPDATE_REJECTION.formatted(userTaskKey, deniedReason);
367:       default ->
368:           throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(intent));
369:     };
370:   }
371: 
372:   private UserTaskCommandProcessor determineProcessorFromUserTaskLifecycleState(
373:       final LifecycleState lifecycleState) {
374: 
375:     final var userTaskIntent =
376:         switch (lifecycleState) {
377:           case CREATING -> UserTaskIntent.CREATE;
378:           case ASSIGNING -> UserTaskIntent.ASSIGN;
379:           case CLAIMING -> UserTaskIntent.CLAIM;
380:           case UPDATING -> UserTaskIntent.UPDATE;
381:           case COMPLETING -> UserTaskIntent.COMPLETE;
382:           case CANCELING -> UserTaskIntent.CANCEL;
383:           default ->
384:               throw new IllegalArgumentException(
385:                   "Unexpected user task lifecycle state: '%s'".formatted(lifecycleState));
386:         };
387: 
388:     return commandProcessors.getCommandProcessor(userTaskIntent);
389:   }
390: 
391:   private ElementInstance getUserTaskElementInstance(final UserTaskRecord userTaskRecord) {
392:     final var elementInstanceKey = userTaskRecord.getElementInstanceKey();
393:     return elementInstanceState.getInstance(elementInstanceKey);
394:   }
395: 
396:   private BpmnElementContext buildContext(final ElementInstance elementInstance) {
397:     final var context = new BpmnElementContextImpl();
398:     context.init(elementInstance.getKey(), elementInstance.getValue(), elementInstance.getState());
399:     return context;
400:   }
401: }
