31: public final class UserTaskUpdateProcessor implements UserTaskCommandProcessor {
32: 
33:   private static final Logger LOGGER = LoggerFactory.getLogger(UserTaskUpdateProcessor.class);
34:   private static final String DEFAULT_ACTION = "update";
35: 
36:   private final StateWriter stateWriter;
37:   private final UserTaskState userTaskState;
38:   private final VariableState variableState;
39:   private final TypedResponseWriter responseWriter;
40:   private final VariableBehavior variableBehavior;
41:   private final UserTaskCommandPreconditionChecker preconditionChecker;
42: 
43:   public UserTaskUpdateProcessor(
44:       final ProcessingState state,
45:       final Writers writers,
46:       final VariableBehavior variableBehavior,
47:       final AuthorizationCheckBehavior authCheckBehavior) {
48:     stateWriter = writers.state();
49:     userTaskState = state.getUserTaskState();
50:     variableState = state.getVariableState();
51:     this.variableBehavior = variableBehavior;
52:     responseWriter = writers.response();
53:     preconditionChecker =
54:         new UserTaskCommandPreconditionChecker(
55:             List.of(LifecycleState.CREATED), "update", state.getUserTaskState(), authCheckBehavior);
56:   }
57: 
58:   @Override
59:   public Either<Rejection, UserTaskRecord> validateCommand(
60:       final TypedRecord<UserTaskRecord> command) {
61:     return preconditionChecker.check(command);
62:   }
63: 
64:   @Override
65:   public void onCommand(
66:       final TypedRecord<UserTaskRecord> command, final UserTaskRecord userTaskRecord) {
67:     final long userTaskKey = command.getKey();
68: 
69:     userTaskRecord.wrapChangedAttributesIfValueChanged(command.getValue());
70:     userTaskRecord.setAction(command.getValue().getActionOrDefault(DEFAULT_ACTION));
71: 
72:     stateWriter.appendFollowUpEvent(userTaskKey, UserTaskIntent.UPDATING, userTaskRecord);
73:   }
74: 
75:   @Override
76:   public void onFinalizeCommand(
77:       final TypedRecord<UserTaskRecord> command, final UserTaskRecord userTaskRecord) {
78:     final long userTaskKey = command.getKey();
79: 
80:     if (command.hasRequestMetadata()) {
81:       stateWriter.appendFollowUpEvent(userTaskKey, UserTaskIntent.UPDATED, userTaskRecord);
82:       responseWriter.writeEventOnCommand(
83:           userTaskKey, UserTaskIntent.UPDATED, userTaskRecord, command);
84:       return;
85:     }
86: 
87:     final var recordRequestMetadata = userTaskState.findRecordRequestMetadata(userTaskKey);
88:     if (recordRequestMetadata.isEmpty()) {
89:       LOGGER.error(
90:           "No request metadata found for userTaskKey='{}', writing 'USER_TASK.UPDATED' without response. "
91:               + "This may indicate a problem with how the update was triggered. "
92:               + "If the update was triggered by a user task variables update, variables will not be merged. "
93:               + "Please report this as a bug.",
94:           userTaskKey);
95:       stateWriter.appendFollowUpEvent(userTaskKey, UserTaskIntent.UPDATED, userTaskRecord);
96:       return;
97:     }
98: 
99:     final var metadata = recordRequestMetadata.get();
100:     switch (metadata.getTriggerType()) {
101:       case USER_TASK -> {
102:         stateWriter.appendFollowUpEvent(userTaskKey, UserTaskIntent.UPDATED, userTaskRecord);
103:         responseWriter.writeResponse(
104:             userTaskKey,
105:             UserTaskIntent.UPDATED,
106:             userTaskRecord,
107:             ValueType.USER_TASK,
108:             metadata.getRequestId(),
109:             metadata.getRequestStreamId());
110:       }
111:       case VARIABLE_DOCUMENT -> {
112:         // Update triggered by a VariableDocument command.
113:         // Retrieve the original VariableDocumentRecord to apply correct variable
114:         // merge logic and write follow-up event.
115:         final var optionalVariableDocumentState =
116:             variableState.findVariableDocumentState(userTaskRecord.getElementInstanceKey());
117:         if (optionalVariableDocumentState.isEmpty()) {
118:           LOGGER.error(
119:               "No variable document state found for elementInstanceKey='{}' during a task update triggered by a user task variables update. "
120:                   + "No variables will be merged, and only 'USER_TASK.UPDATED' will be written. "
121:                   + "This may be caused by a corrupted or incomplete variable update request. "
122:                   + "Please report this as a bug.",
123:               userTaskRecord.getElementInstanceKey());
124:           stateWriter.appendFollowUpEvent(userTaskKey, UserTaskIntent.UPDATED, userTaskRecord);
125:           return;
126:         }
127: 
128:         final var variableDocumentState = optionalVariableDocumentState.get();
129:         final var variableDocumentRecord = variableDocumentState.getRecord();
130:         mergeVariables(userTaskRecord, variableDocumentRecord);
131: 
132:         // Write follow-up events
133:         stateWriter.appendFollowUpEvent(userTaskKey, UserTaskIntent.UPDATED, userTaskRecord);
134:         final long variableDocumentKey = variableDocumentState.getKey();
135:         stateWriter.appendFollowUpEvent(
136:             variableDocumentKey, VariableDocumentIntent.UPDATED, variableDocumentRecord);
137: 
138:         responseWriter.writeResponse(
139:             variableDocumentKey,
140:             VariableDocumentIntent.UPDATED,
141:             variableDocumentRecord,
142:             ValueType.VARIABLE_DOCUMENT,
143:             metadata.getRequestId(),
144:             metadata.getRequestStreamId());
145:       }
146:       default ->
147:           throw new IllegalArgumentException(
148:               "Unexpected user task transition trigger type: '%s'"
149:                   .formatted(metadata.getTriggerType()));
150:     }
151:   }
152: 
153:   private void mergeVariables(
154:       final UserTaskRecord userTaskRecord, final VariableDocumentRecord variableRecord) {
155:     switch (variableRecord.getUpdateSemantics()) {
156:       case LOCAL ->
157:           variableBehavior.mergeLocalDocument(
158:               userTaskRecord.getElementInstanceKey(),
159:               userTaskRecord.getProcessDefinitionKey(),
160:               userTaskRecord.getProcessInstanceKey(),
161:               userTaskRecord.getBpmnProcessIdBuffer(),
162:               userTaskRecord.getTenantId(),
163:               variableRecord.getVariablesBuffer());
164:       case PROPAGATE ->
165:           variableBehavior.mergeDocument(
166:               userTaskRecord.getElementInstanceKey(),
167:               userTaskRecord.getProcessDefinitionKey(),
168:               userTaskRecord.getProcessInstanceKey(),
169:               userTaskRecord.getBpmnProcessIdBuffer(),
170:               userTaskRecord.getTenantId(),
171:               variableRecord.getVariablesBuffer());
172:       default ->
173:           throw new IllegalStateException(
174:               "Unexpected variable update semantic: '%s'. Expected either 'LOCAL' or 'PROPAGATE'."
175:                   .formatted(variableRecord.getUpdateSemantics()));
176:     }
177:   }
178: }
