227:   private void storeUserTaskRecordRequestMetadata(final TypedRecord<UserTaskRecord> command) {
228:     if (!command.hasRequestMetadata()) {
229:       return;
230:     }
231: 
232:     final var metadata =
233:         new UserTaskTransitionTriggerRequestMetadata()
234:             .setIntent(command.getIntent())
235:             .setTriggerType(ValueType.USER_TASK)
236:             .setRequestId(command.getRequestId())
237:             .setRequestStreamId(command.getRequestStreamId());
238:     userTaskState.storeRecordRequestMetadata(command.getValue().getUserTaskKey(), metadata);
239:   }
