48:   @Override
49:   public SearchQuery toSearchQuery(final IncidentFilter filter) {
50:     final var keyQuery = getKeyQuery(filter.incidentKeyOperations());
51:     final var processDefinitionKeyQuery =
52:         getProcessDefinitionKeyQuery(filter.processDefinitionKeyOperations());
53:     final var processDefinitionIdQuery = getProcessDefinitionIds(filter.processDefinitionIdOperations());
54:     final var processInstanceKeyQuery = getProcessInstanceKeyQuery(filter.processInstanceKeyOperations());
55:     final var errorTypeQuery = getErrorTypeQuery(filter.errorTypeOperations());
56:     final var errorMessageQuery = getErrorMessageQuery(filter.errorMessageOperations());
57:     final var flowNodeIdQuery = getFlowNodeIdQuery(filter.flowNodeIdOperations());
58:     final var flowNodeInstanceKeyQuery = getFlowNodeInstanceKeyQuery(filter.flowNodeInstanceKeys());
59:     final var creationTimeQuery = getCreationTimeQuery(filter.creationTime());
60:     final var stateQuery = getStateQuery(filter.states());
61:     final var treePathQuery = getTreePathQuery(filter.treePath());
62:     final var jobKeyQuery = getJobKeyQuery(filter.jobKeys());
63:     final var tenantIdQuery = getTenantIdQuery(filter.tenantIds());
64:     final var errorMessageHashesQuery = getErrorMessageHashesQuery(filter.errorMessageHashOperations());
65: 
66:     return and(
67:         keyQuery,
68:         processDefinitionKeyQuery,
69:         processDefinitionIdQuery,
70:         processInstanceKeyQuery,
71:         errorTypeQuery,
72:         errorMessageQuery,
73:         flowNodeIdQuery,
74:         flowNodeInstanceKeyQuery,
75:         creationTimeQuery,
76:         stateQuery,
77:         treePathQuery,
78:         jobKeyQuery,
79:         tenantIdQuery,
80:         errorMessageHashesQuery);
