279:   private <R> R mapIncidentErrorHashCodesToProcessInstanceKeys(
280:       final List<Integer> incidentErrorHashCodes,
281:       final List<Operation<Long>> existingProcessInstanceKeyOperations,
282:       final Supplier<R> fnEmptyResult,
283:       final Function<Set<Long>, R> fnResult) {
284: 
285:     // Search for active incidents that match the given error message hash codes
286:     final var incidentFilter =
287:         FilterBuilders.incident(
288:             f -> f.errorMessageHashOperations(incidentErrorHashCodes).states(IncidentState.ACTIVE));
289: 
290:     final var incidentResult = searchIncidents(IncidentQuery.of(f -> f.filter(incidentFilter)));
291: 
292:     if (incidentResult.items().isEmpty()) {
293:       return fnEmptyResult.get();
294:     }
295: 
296:     // Collect all relevant process instance keys (from both incidents and existing filter)
297:     final Set<Long> processInstanceKeys = new HashSet<>();
298:     incidentResult.items().forEach(i -> processInstanceKeys.add(i.processInstanceKey()));
299: 
300:     for (final var op : existingProcessInstanceKeyOperations) {
301:       if (op.operator().equals(Operator.EQUALS)) {
302:         processInstanceKeys.add(op.value());
303:       } else if (op.operator().equals(Operator.IN)) {
304:         processInstanceKeys.addAll(op.values());
305:       }
306:     }
307:     return fnResult.apply(processInstanceKeys);
308:   }
