39:  * GatewayRestConfiguration.ProcessCacheConfiguration} properties.
40:  */
41: public class ProcessCache {
42: 
43:   public static final String NAMESPACE = "camunda.gateway.rest.cache";
44:   private static final Logger LOGGER = LoggerFactory.getLogger(ProcessCache.class);
45:   private final LoadingCache<Long, ProcessCacheItem> cache;
46:   private final ProcessElementProvider processElementProvider;
47: 
48:   public ProcessCache(
49:       final GatewayRestConfiguration configuration,
50:       final ProcessElementProvider processElementProvider,
51:       final BrokerTopologyManager brokerTopologyManager,
52:       final MeterRegistry meterRegistry) {
53:     this.processElementProvider = processElementProvider;
54:     final var statsCounter = new CaffeineCacheStatsCounter(NAMESPACE, "process", meterRegistry);
55:     final var cacheBuilder =
56:         Caffeine.newBuilder()
57:             .maximumSize(configuration.getProcessCache().getMaxSize())
58:             .recordStats(() -> statsCounter);
59:     final var expirationIdle = configuration.getProcessCache().getExpirationIdleMillis();
60:     if (expirationIdle != null && expirationIdle > 0) {
61:       cacheBuilder.expireAfterAccess(expirationIdle, TimeUnit.MILLISECONDS);
62:     }
63:     cache = cacheBuilder.build(new ProcessCacheLoader());
64: 
65:     brokerTopologyManager.addTopologyListener(new ProcessCacheInvalidator(this));
66:   }
67: 
68:   public ProcessCacheItem getCacheItem(final long processDefinitionKey) {
69:     return cache.get(processDefinitionKey);
70:   }
71: 
72:   public Map<Long, ProcessCacheItem> getCacheItems(final Set<Long> processDefinitionKeys) {
73:     return cache.getAll(processDefinitionKeys);
74:   }
75: 
76:   public Map<Long, ProcessCacheItem> getUserTaskNames(final List<UserTaskEntity> items) {
77:     return getCacheItems(
78:         items.stream().map(UserTaskEntity::processDefinitionKey).collect(Collectors.toSet()));
79:   }
80: 
81:   public String getUserTaskName(final UserTaskEntity userTask) {
82:     return getCacheItem(userTask.processDefinitionKey()).getName(userTask.elementId());
83:   }
84: 
85:   public Map<Long, ProcessCacheItem> getNames(final List<FlowNodeInstanceEntity> items) {
86:     return getCacheItems(
87:         items.stream()
88:             .map(FlowNodeInstanceEntity::processDefinitionKey)
89:             .collect(Collectors.toSet()));
90:   }
91: 
92:   public String getElementName(final FlowNodeInstanceEntity element) {
93:     return getCacheItem(element.processDefinitionKey()).getName(element.flowNodeId());
94:   }
95: 
96:   public void invalidate() {
97:     cache.invalidateAll();
98:   }
99: 
100:   private final class ProcessCacheLoader implements CacheLoader<Long, ProcessCacheItem> {
101: 
102:     @Override
103:     public ProcessCacheItem load(final Long processDefinitionKey) {
104:       final var elements = new HashMap<String, String>();
105:       processElementProvider.extractElementNames(
106:           processDefinitionKey, (pdKey, node) -> elements.put(node.id(), node.name()));
107:       return new ProcessCacheItem(Collections.unmodifiableMap(elements));
108:     }
109: 
110:     @Override
111:     public Map<Long, ProcessCacheItem> loadAll(final Set<? extends Long> processDefinitionKeys) {
112:       final var processMap = new HashMap<Long, Map<String, String>>();
113:       processElementProvider.extractElementNames(
114:           (Set<Long>) processDefinitionKeys,
115:           (pdKey, element) -> {
116:             final var elementMap = processMap.computeIfAbsent(pdKey, key -> new HashMap<>());
117:             elementMap.put(element.id(), element.name());
118:           });
119:       return processMap.entrySet().stream()
120:           .collect(
121:               Collectors.toMap(
122:                   Map.Entry::getKey,
123:                   entry -> new ProcessCacheItem(Collections.unmodifiableMap(entry.getValue()))));
124:     }
125:   }
126: 
127:   private final class ProcessCacheInvalidator implements BrokerTopologyListener {
128:     private final ProcessCache cache;
129: 
130:     public ProcessCacheInvalidator(final ProcessCache cache) {
131:       this.cache = cache;
132:     }
133: 
134:     @Override
135:     public void completedClusterChange() {
136:       cache.invalidate();
137:       LOGGER.debug("Process cache invalidated");
138:     }
139:   }
140: }
