1521:   private static Either<List<String>, SearchQueryPage> toSearchQueryPage(
1522:       final SearchQueryPageRequest requestedPage) {
1523:     if (requestedPage == null) {
1524:       return Either.right(null);
1525:     }
1526: 
1527:     final Object[] searchAfter = toArrayOrNull(requestedPage.getSearchAfter());
1528:     final Object[] searchBefore = toArrayOrNull(requestedPage.getSearchBefore());
1529: 
1530:     if (searchAfter != null && searchBefore != null) {
1531:       return Either.left(List.of(ERROR_SEARCH_BEFORE_AND_AFTER));
1532:     }
1533:     if (requestedPage.getFrom() != null && (searchAfter != null || searchBefore != null)) {
1534:       return Either.left(List.of(ERROR_SEARCH_BEFORE_AND_AFTER_AND_FROM));
1535:     }
1536: 
1537:     return Either.right(
1538:         SearchQueryPage.of(
1539:             (p) ->
1540:                 p.size(requestedPage.getLimit())
1541:                     .from(requestedPage.getFrom())
1542:                     .searchAfter(searchAfter)
1543:                     .searchBefore(searchBefore)));
1544:   }
