1549:           final Supplier<B> builderSupplier,
1550:           final BiFunction<F, B, List<String>> sortFieldMapper) {
1551:     if (sorting != null && !sorting.isEmpty()) {
1552:       final List<String> validationErrors = new ArrayList<>();
1553:       final var builder = builderSupplier.get();
1554:       for (final SearchQuerySortRequest<F> sort : sorting) {
