1495:                   }
1496:                   if (filter.getValue() == null
1497:                       || filter.getValue().equals(EMPTY_ADVANCED_STRING_FILTER)
1498:                       || filter.getValue().equals(EMPTY_BASIC_STRING_FILTER)) {
1499:                     validationErrors.add(ERROR_MESSAGE_NULL_VARIABLE_VALUE);
1500:                   }
