1058:       if (!CollectionUtils.isEmpty(filter.getProcessInstanceVariables())) {
1059:         final Either<List<String>, List<VariableValueFilter>> either =
1060:             toVariableValueFilters(filter.getProcessInstanceVariables());
1061:         if (either.isLeft()) {
1062:           validationErrors.addAll(either.getLeft());
