364:   @Test
365:   void shouldSortByDecisionRequirementsId() {
366:     // when
367:     final var resultAsc =
368:         camundaClient
369:             .newDecisionRequirementsSearchRequest()
370:             .sort(s -> s.decisionRequirementsId().asc())
371:             .send()
372:             .join();
373:     final var resultDesc =
374:         camundaClient
375:             .newDecisionRequirementsSearchRequest()
376:             .sort(s -> s.decisionRequirementsId().desc())
377:             .send()
378:             .join();
379: 
380:     // Extract unique IDs from the results
381:     // As we have 2 process with the same definition, it is necessary check the full list of IDs
382:     final List<String> uniqueAscIds =
383:         resultAsc.items().stream()
384:             .map(item -> item.getDmnDecisionRequirementsId())
385:             .distinct()
386:             .collect(Collectors.toList());
387: 
388:     final List<String> uniqueDescIds =
389:         resultDesc.items().stream()
390:             .map(item -> item.getDmnDecisionRequirementsId())
391:             .distinct()
392:             .collect(Collectors.toList());
393: 
394:     // Ensure there are at least two unique IDs to compare
395:     assertThat(uniqueAscIds.size()).isGreaterThan(1);
396:     assertThat(uniqueDescIds.size()).isGreaterThan(1);
397: 
398:     // Assert that the first unique ID in ascending order is less than the second unique ID
399:     assertThat(uniqueAscIds.get(0)).isLessThan(uniqueAscIds.get(1));
400: 
401:     // Assert that the first unique ID in descending order is greater than the second unique ID
402:     assertThat(uniqueDescIds.get(0)).isGreaterThan(uniqueDescIds.get(1));
403:   }
