488:         camundaClient.newDecisionRequirementsSearchRequest().page(p -> p.limit(1)).send().join();
489:     assertThat(result.items().size()).isEqualTo(1);
490:     final var key = result.items().getFirst().getDecisionRequirementsKey();
491:     // apply searchAfter
492:     final var resultAfter =
493:         camundaClient
494:             .newDecisionRequirementsSearchRequest()
495:             .page(p -> p.searchAfter(result.page().endCursor()))
496:             .send()
497:             .join();
498: 
499:     assertThat(resultAfter.items().size()).isEqualTo(2);
500: 
501:     // apply searchBefore
502:     final var resultBefore =
503:         camundaClient
504:             .newDecisionRequirementsSearchRequest()
505:             .page(p -> p.searchBefore(resultAfter.page().startCursor()))
506:             .send()
507:             .join();
508:     assertThat(result.items().size()).isEqualTo(1);
509:     assertThat(resultBefore.items().getFirst().getDecisionRequirementsKey()).isEqualTo(key);
510:   }
