61:   @BeforeAll
62:   public static void beforeAll() {
63:     Objects.requireNonNull(camundaClient);
64:     final List<String> processes =
65:         List.of(
66:             "service_tasks_v1.bpmn",
67:             "service_tasks_v2.bpmn",
68:             "incident_process_v1.bpmn",
69:             "incident_process_v2.bpmn",
70:             "manual_process.bpmn",
71:             "parent_process_v1.bpmn",
72:             "child_process_v1.bpmn");
73:     processes.forEach(
74:         process ->
75:             DEPLOYED_PROCESSES.addAll(
76:                 deployResource(camundaClient, String.format("process/%s", process))
77:                     .getProcesses()));
78: 
79:     waitForProcessesToBeDeployed(camundaClient, DEPLOYED_PROCESSES.size());
80: 
81:     PROCESS_INSTANCES.add(
82:         startProcessInstance(camundaClient, "service_tasks_v1", "{\"xyz\":\"foo\"}"));
83:     PROCESS_INSTANCES.add(
84:         startProcessInstance(
85:             camundaClient, "service_tasks_v1", "{\"xyz\": \"bar\",\"abc\": \"mnp\"}"));
86:     PROCESS_INSTANCES.add(
87:         startProcessInstance(camundaClient, "service_tasks_v2", "{\"path\":222}"));
88:     PROCESS_INSTANCES.add(startProcessInstance(camundaClient, "manual_process"));
89:     final ProcessInstanceEvent processInstanceWithIncident =
90:         startProcessInstance(camundaClient, "incident_process_v1");
91:     PROCESS_INSTANCES.add(startProcessInstance(camundaClient, "incident_process_v2"));
92:     processInstanceWithIncidentKey = processInstanceWithIncident.getProcessInstanceKey();
93:     PROCESS_INSTANCES.add(processInstanceWithIncident);
94:     PROCESS_INSTANCES.add(startProcessInstance(camundaClient, "parent_process_v1"));
95: 
96:     waitForProcessInstancesToStart(camundaClient, 8);
97:     waitForElementInstances(camundaClient, 24);
98:     waitUntilElementInstanceHasIncidents(camundaClient, 2);
99:     waitUntilProcessInstanceHasIncidents(camundaClient, 2);
100:     // store element instances for querying
101:     allElementInstances =
102:         camundaClient
103:             .newElementInstanceSearchRequest()
104:             .page(p -> p.limit(100))
105:             .sort(s -> s.elementId().asc())
106:             .send()
107:             .join()
108:             .items();
109:     elementInstance = allElementInstances.getFirst();
110:     elementInstanceWithIncident =
111:         allElementInstances.stream()
112:             .filter(f -> f.getIncidentKey() != null)
113:             .findFirst()
114:             .orElseThrow();
115:   }
