1314:   private static void deployProcess(
1315:       final String processId,
1316:       final String resourceName,
1317:       final String userTaskName,
1318:       final String candidateGroup,
1319:       final String candidateUser) {
1320:     final DateTimeFormatter dateFormat =
1321:         DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
1322:     final ZoneId utcZoneId = ZoneId.of("UTC");
1323: 
1324:     final LocalDateTime now = LocalDateTime.now(utcZoneId);
1325:     final LocalDateTime dayBefore = now.minusDays(1);
1326: 
1327:     camundaClient
1328:         .newDeployResourceCommand()
1329:         .addProcessModel(
1330:             Bpmn.createExecutableProcess(processId)
1331:                 .startEvent()
1332:                 .userTask(userTaskName)
1333:                 .zeebeUserTask()
1334:                 .zeebeDueDate(dayBefore.format(dateFormat))
1335:                 .zeebeFollowUpDate(dayBefore.format(dateFormat))
1336:                 .zeebeCandidateGroups(candidateGroup)
1337:                 .zeebeCandidateUsers(candidateUser)
1338:                 .endEvent()
1339:                 .done(),
1340:             resourceName)
1341:         .send()
1342:         .join();
1343:   }
