1410:         .assignee("demo")
1411:         .action("assignee")
1412:         .send()
1413:         .join();
1414: 
1415:     camundaClient.newUserTaskCompleteCommand(userTaskKeyTaskAssigned).send().join();
1416: 
1417:     Awaitility.await("should export Assigned task and Completed to ElasticSearch")
1418:         .atMost(TIMEOUT_DATA_AVAILABILITY)
1419:         .ignoreExceptions() // Ignore exceptions and continue retrying
1420:         .untilAsserted(
1421:             () -> {
1422:               final var result =
1423:                   camundaClient
1424:                       .newUserTaskSearchRequest()
1425:                       .filter(f -> f.assignee("demo"))
1426:                       .send()
1427:                       .join();
1428:               assertThat(result.items().size()).isEqualTo(1);
1429:               final var resultComplete =
1430:                   camundaClient
1431:                       .newUserTaskSearchRequest()
1432:                       .filter(f -> f.state(UserTaskState.COMPLETED))
1433:                       .send()
1434:                       .join();
1435:               assertThat(resultComplete.items().size()).isEqualTo(1);
1436:             });
1437:   }
