116:    * multiple queries to the secondary database.
117:    *
118:    * @param filter the filter to use
119:    * @param authentication the authentication to use
120:    * @param shouldAbort if the process should be aborted
121:    * @return a set of all found incident items
122:    */
123:   public Set<Item> fetchIncidentItems(
124:       final int partitionId,
125:       final ProcessInstanceFilter filter,
126:       final Authentication authentication,
127:       final Supplier<Boolean> shouldAbort) {
128:     // first fetch all matching processInstances
129:     final var processInstanceKeys =
130:         fetchProcessInstanceItems(partitionId, filter, authentication, shouldAbort).stream()
131:             .map(Item::processInstanceKey)
132:             .toList();
133: 
134:     // then fetch all incidents of the matching processInstances
135:     return getIncidentItemsOfProcessInstanceKeys(
136:         new ArrayList<>(processInstanceKeys), authentication, shouldAbort);
