239:   private final class ProcessInstancePageFetcher implements ItemPageFetcher<ProcessInstanceFilter> {
240:     @Override
241:     public ItemPage fetchItems(
242:         final ProcessInstanceFilter filter,
243:         final String searchAfter,
244:         final Authentication authentication) {
245:       final var securityContext =
246:           createSecurityContext(
247:               authentication, Authorization.of(a -> a.processDefinition().readProcessInstance()));
248:       final var page =
249:           SearchQueryPageBuilders.page().size(queryPageSize).after(searchAfter).build();
250:       final var query =
251:           SearchQueryBuilders.processInstanceSearchQuery()
252:               .filter(filter)
253:               .page(page)
254:               .resultConfig(c -> c.onlyKey(true))
255:               .build();
256: 
257:       final SearchQueryResult<ProcessInstanceEntity> result =
258:           searchClientsProxy.withSecurityContext(securityContext).searchProcessInstances(query);
259: 
260:       return new ItemPage(
261:           result.items().stream()
262:               .map(pi -> new Item(pi.processInstanceKey(), pi.processInstanceKey()))
263:               .collect(Collectors.toList()),
264:           result.searchAfterCursor(),
265:           result.total());
266:     }
267:   }
