270:     @Override
271:     public ItemPage fetchItems(
272:         final IncidentFilter filter,
273:         final String searchAfter,
274:         final Authentication authentication) {
275:       final var securityContext =
276:           createSecurityContext(
277:               authentication, Authorization.of(a -> a.processDefinition().readProcessInstance()));
278:       final var page =
279:           SearchQueryPageBuilders.page().size(queryPageSize).after(searchAfter).build();
280:       final var query = SearchQueryBuilders.incidentSearchQuery().filter(filter).page(page).build();
281: 
282:       final var result =
283:           searchClientsProxy.withSecurityContext(securityContext).searchIncidents(query);
284: 
285:       return new ItemPage(
286:           result.items().stream()
287:               .map(pi -> new Item(pi.incidentKey(), pi.processInstanceKey()))
288:               .collect(Collectors.toList()),
289:           result.searchAfterCursor(),
290:           result.total());
291:     }
292:   }
