798:   private static List<EvaluatedDecisionInputItem> toEvaluatedInputs(
799:       final List<DecisionInstanceInputEntity> decisionInstanceInputEntities) {
800:     if (decisionInstanceInputEntities == null) {
801:       return null;
802:     }
803:     return decisionInstanceInputEntities.stream()
804:         .map(
805:             input ->
806:                 new EvaluatedDecisionInputItem()
