842:   private static DecisionInstanceStateEnum toDecisionInstanceStateEnum(
843:       final DecisionInstanceState state) {
844:     if (state == null) {
845:       return null;
846:     }
847:     return switch (state) {
848:       case EVALUATED -> DecisionInstanceStateEnum.EVALUATED;
849:       case FAILED -> DecisionInstanceStateEnum.FAILED;
850:       case UNSPECIFIED -> DecisionInstanceStateEnum.UNSPECIFIED;
851:       default -> DecisionInstanceStateEnum.UNKNOWN;
852:     };
853:   }
854: 
855:   private static DecisionDefinitionTypeEnum toDecisionDefinitionTypeEnum(
856:       final DecisionDefinitionType decisionDefinitionType) {
857:     if (decisionDefinitionType == null) {
858:       return null;
859:     }
860:     return switch (decisionDefinitionType) {
861:       case DECISION_TABLE -> DecisionDefinitionTypeEnum.DECISION_TABLE;
862:       case LITERAL_EXPRESSION -> DecisionDefinitionTypeEnum.LITERAL_EXPRESSION;
863:       case UNSPECIFIED -> DecisionDefinitionTypeEnum.UNSPECIFIED;
864:       default -> DecisionDefinitionTypeEnum.UNKNOWN;
865:     };
866:   }
