166:   public static Either<List<String>, ProcessDefinitionStatisticsFilter>
167:       toProcessDefinitionStatisticsFilter(
168:           final long processDefinitionKey,
169:           final io.camunda.zeebe.gateway.protocol.rest.ProcessDefinitionStatisticsFilter filter) {
170:     final List<String> validationErrors = new ArrayList<>();
171: 
172:     final Either<List<String>, ProcessDefinitionStatisticsFilter.Builder> builder =
173:         toBaseProcessInstanceFilterFields(processDefinitionKey, filter);
174:     if (builder.isLeft()) {
175:       validationErrors.addAll(builder.getLeft());
176:     }
177: 
178:     if (filter != null) {
179:       if (filter.get$Or() != null && !filter.get$Or().isEmpty()) {
180:         for (final BaseProcessInstanceFilterFields or : filter.get$Or()) {
181:           final var orBuilder = toBaseProcessInstanceFilterFields(processDefinitionKey, or);
182:           if (orBuilder.isLeft()) {
183:             validationErrors.addAll(orBuilder.getLeft());
184:           } else {
185:             builder.get().addOrOperation(orBuilder.get().build());
186:           }
187:         }
188:       }
189:     }
190: 
191:     return validationErrors.isEmpty()
192:         ? Either.right(builder.get().build())
193:         : Either.left(validationErrors);
194:   }
