196:   private static Either<List<String>, ProcessDefinitionStatisticsFilter.Builder>
197:       toBaseProcessInstanceFilterFields(
198:           final long processDefinitionKey, final BaseProcessInstanceFilterFields filter) {
199:     final var builder = FilterBuilders.processDefinitionStatisticsFilter(processDefinitionKey);
200:     final List<String> validationErrors = new ArrayList<>();
201:     if (filter != null) {
202:       ofNullable(filter.getProcessInstanceKey())
203:           .map(mapToOperations(Long.class))
204:           .ifPresent(builder::processInstanceKeyOperations);
205:       ofNullable(filter.getParentProcessInstanceKey())
206:           .map(mapToOperations(Long.class))
207:           .ifPresent(builder::parentProcessInstanceKeyOperations);
208:       ofNullable(filter.getParentElementInstanceKey())
209:           .map(mapToOperations(Long.class))
210:           .ifPresent(builder::parentFlowNodeInstanceKeyOperations);
211:       ofNullable(filter.getStartDate())
212:           .map(mapToOperations(OffsetDateTime.class))
213:           .ifPresent(builder::startDateOperations);
214:       ofNullable(filter.getEndDate())
215:           .map(mapToOperations(OffsetDateTime.class))
216:           .ifPresent(builder::endDateOperations);
217:       ofNullable(filter.getState())
218:           .map(mapToOperations(String.class, new ProcessInstanceStateConverter()))
219:           .ifPresent(builder::stateOperations);
220:       ofNullable(filter.getHasIncident()).ifPresent(builder::hasIncident);
221:       ofNullable(filter.getTenantId())
222:           .map(mapToOperations(String.class))
223:           .ifPresent(builder::tenantIdOperations);
224:       ofNullable(filter.getBatchOperationId())
225:           .map(mapToOperations(String.class))
226:           .ifPresent(builder::batchOperationIdOperations);
227:       ofNullable(filter.getErrorMessage())
228:           .map(mapToOperations(String.class))
229:           .ifPresent(builder::errorMessageOperations);
230:       ofNullable(filter.getHasRetriesLeft()).ifPresent(builder::hasRetriesLeft);
231:       ofNullable(filter.getElementId())
232:           .map(mapToOperations(String.class))
233:           .ifPresent(builder::flowNodeIdOperations);
234:       ofNullable(filter.getHasElementInstanceIncident())
235:           .ifPresent(builder::hasFlowNodeInstanceIncident);
236:       ofNullable(filter.getElementInstanceState())
237:           .map(mapToOperations(String.class))
238:           .ifPresent(builder::flowNodeInstanceStateOperations);
239:       ofNullable(filter.getIncidentErrorHashCode()).ifPresent(builder::incidentErrorHashCodes);
240:       if (!CollectionUtils.isEmpty(filter.getVariables())) {
241:         final Either<List<String>, List<VariableValueFilter>> either =
242:             toVariableValueFilters(filter.getVariables());
243:         if (either.isLeft()) {
244:           validationErrors.addAll(either.getLeft());
245:         } else {
246:           builder.variables(either.get());
247:         }
248:       }
249:     }
250:     return validationErrors.isEmpty() ? Either.right(builder) : Either.left(validationErrors);
251:   }
