517:   private static List<String> applyDecisionInstanceSortField(
518:       final DecisionInstanceSearchQuerySortRequest.FieldEnum field,
519:       final DecisionInstanceSort.Builder builder) {
520:     final List<String> validationErrors = new ArrayList<>();
521:     if (field == null) {
522:       validationErrors.add(ERROR_SORT_FIELD_MUST_NOT_BE_NULL);
523:     } else {
524:       switch (field) {
525:         case DECISION_INSTANCE_KEY -> builder.decisionInstanceKey();
526:         case DECISION_INSTANCE_ID -> builder.decisionInstanceId();
527:         case STATE -> builder.state();
528:         case EVALUATION_DATE -> builder.evaluationDate();
529:         case EVALUATION_FAILURE -> builder.evaluationFailure();
530:         case PROCESS_DEFINITION_KEY -> builder.processDefinitionKey();
531:         case PROCESS_INSTANCE_KEY -> builder.processInstanceKey();
532:         case DECISION_DEFINITION_KEY -> builder.decisionDefinitionKey();
533:         case DECISION_DEFINITION_ID -> builder.decisionDefinitionId();
534:         case DECISION_DEFINITION_NAME -> builder.decisionDefinitionName();
535:         case DECISION_DEFINITION_VERSION -> builder.decisionDefinitionVersion();
536:         case DECISION_DEFINITION_TYPE -> builder.decisionDefinitionType();
537:         case TENANT_ID -> builder.tenantId();
538:         default -> validationErrors.add(ERROR_UNKNOWN_SORT_BY.formatted(field));
539:       }
540:     }
541:     return validationErrors;
542:   }
