1535:   private static Either<List<String>, SearchQueryPage> toSearchQueryPage(
1536:       final SearchQueryPageRequest requestedPage) {
1537:     if (requestedPage == null) {
1538:       return Either.right(null);
1539:     }
1540: 
1541:     final Object[] searchAfter = toArrayOrNull(requestedPage.getSearchAfter());
1542:     final Object[] searchBefore = toArrayOrNull(requestedPage.getSearchBefore());
1543: 
1544:     if (searchAfter != null && searchBefore != null) {
1545:       return Either.left(List.of(ERROR_SEARCH_BEFORE_AND_AFTER));
1546:     }
1547:     if (requestedPage.getFrom() != null && (searchAfter != null || searchBefore != null)) {
1548:       return Either.left(List.of(ERROR_SEARCH_BEFORE_AND_AFTER_AND_FROM));
1549:     }
1550: 
1551:     return Either.right(
1552:         SearchQueryPage.of(
1553:             (p) ->
1554:                 p.size(requestedPage.getLimit())
1555:                     .from(requestedPage.getFrom())
1556:                     .searchAfter(searchAfter)
1557:                     .searchBefore(searchBefore)));
1558:   }
