1560:   private static <T, B extends SortOption.AbstractBuilder<B> & ObjectBuilder<T>, F>
1561:       Either<List<String>, T> toSearchQuerySort(
1562:           final List<SearchQuerySortRequest<F>> sorting,
1563:           final Supplier<B> builderSupplier,
1564:           final BiFunction<F, B, List<String>> sortFieldMapper) {
1565:     if (sorting != null && !sorting.isEmpty()) {
1566:       final List<String> validationErrors = new ArrayList<>();
1567:       final var builder = builderSupplier.get();
1568:       for (final SearchQuerySortRequest<F> sort : sorting) {
1569:         validationErrors.addAll(sortFieldMapper.apply(sort.field(), builder));
1570:         applySortOrder(sort.order(), builder);
1571:       }
1572: 
1573:       return validationErrors.isEmpty()
1574:           ? Either.right(builder.build())
1575:           : Either.left(validationErrors);
1576:     }
1577: 
1578:     return Either.right(null);
1579:   }
