1610:           S extends SortOption>
1611:       Either<ProblemDetail, T> buildSearchQuery(
1612:           final Either<List<String>, F> filter,
1613:           final Either<List<String>, S> sorting,
1614:           final Either<List<String>, SearchQueryPage> page,
1615:           final Supplier<B> queryBuilderSupplier) {
1616:     final List<String> validationErrors = new ArrayList<>();
1617:     if (filter.isLeft()) {
1618:       validationErrors.addAll(filter.getLeft());
1619:     }
1620:     if (sorting.isLeft()) {
1621:       validationErrors.addAll(sorting.getLeft());
1622:     }
1623:     if (page.isLeft()) {
1624:       validationErrors.addAll(page.getLeft());
1625:     }
1626: 
1627:     return getResult(
1628:         RequestValidator.createProblemDetail(validationErrors),
1629:         () ->
1630:             queryBuilderSupplier
1631:                 .get()
1632:                 .page(page.get())
1633:                 .filter(filter.get())
1634:                 .sort(sorting.get())
1635:                 .build());
1636:   }
