1496:   private static Either<List<String>, List<VariableValueFilter>> toVariableValueFilters(
1497:       final List<VariableValueFilterProperty> filters) {
1498:     if (CollectionUtils.isEmpty(filters)) {
1499:       return Either.right(List.of());
1500:     }
1501: 
1502:     final List<String> validationErrors = new ArrayList<>();
1503:     final List<VariableValueFilter> variableValueFilters =
1504:         filters.stream()
1505:             .flatMap(
1506:                 filter -> {
1507:                   if (filter.getName() == null) {
1508:                     validationErrors.add(ERROR_MESSAGE_NULL_VARIABLE_NAME);
1509:                   }
1510:                   if (filter.getValue() == null
1511:                       || filter.getValue().equals(EMPTY_ADVANCED_STRING_FILTER)
1512:                       || filter.getValue().equals(EMPTY_BASIC_STRING_FILTER)) {
1513:                     validationErrors.add(ERROR_MESSAGE_NULL_VARIABLE_VALUE);
1514:                   }
1515:                   // if there is no validation error overall, process the filter
1516:                   return validationErrors.isEmpty()
1517:                       ? toVariableValueFilters(filter.getName(), filter.getValue()).stream()
1518:                       : Stream.empty();
1519:                 })
1520:             .toList();
1521:     return validationErrors.isEmpty()
1522:         ? Either.right(variableValueFilters)
1523:         : Either.left(validationErrors);
1524:   }
