36: import java.util.stream.Collectors;
37: import org.slf4j.Logger;
38: import org.slf4j.LoggerFactory;
39: 
40: public class BatchOperationExecutionScheduler implements StreamProcessorLifecycleAware {
41: 
42:   private static final Logger LOG = LoggerFactory.getLogger(BatchOperationExecutionScheduler.class);
43:   private final Duration pollingInterval;
44:   private final int chunkSize;
45: 
46:   private final BatchOperationState batchOperationState;
47:   private ReadonlyStreamProcessorContext processingContext;
48:   private final BatchOperationItemProvider entityKeyProvider;
49:   private final BatchOperationMetrics metrics;
50:   private final int partitionId;
51: 
52:   /** Marks if this scheduler is currently executing or not. */
53:   private final AtomicBoolean executing = new AtomicBoolean(false);
54: 
55:   public BatchOperationExecutionScheduler(
56:       final Supplier<ScheduledTaskState> scheduledTaskStateFactory,
57:       final BatchOperationItemProvider entityKeyProvider,
58:       final EngineConfiguration engineConfiguration,
59:       final int partitionId,
60:       final BatchOperationMetrics metrics) {
61:     batchOperationState = scheduledTaskStateFactory.get().getBatchOperationState();
62:     this.entityKeyProvider = entityKeyProvider;
63:     pollingInterval = engineConfiguration.getBatchOperationSchedulerInterval();
64:     chunkSize = engineConfiguration.getBatchOperationChunkSize();
65:     this.metrics = metrics;
66:     this.partitionId = partitionId;
67:   }
68: 
69:   @Override
70:   public void onRecovered(final ReadonlyStreamProcessorContext context) {
71:     processingContext = context;
72:     scheduleExecution();
73:   }
74: 
75:   @Override
76:   public void onResumed() {
77:     scheduleExecution();
78:   }
79: 
80:   private void scheduleExecution() {
81:     if (!executing.get()) {
82:       processingContext
83:           .getScheduleService()
84:           .runDelayedAsync(pollingInterval, this::execute, AsyncTaskGroup.BATCH_OPERATIONS);
85:     } else {
86:       LOG.warn("Execution is already in progress, skipping scheduling.");
87:     }
88:   }
89: 
90:   private TaskResult execute(final TaskResultBuilder taskResultBuilder) {
91:     try {
92:       LOG.trace("Looking for pending batch operations to execute (scheduled).");
93:       executing.set(true);
94:       batchOperationState.foreachPendingBatchOperation(
95:           bo -> executeBatchOperation(bo, taskResultBuilder));
96:       return taskResultBuilder.build();
97:     } finally {
98:       executing.set(false);
99:       scheduleExecution();
100:     }
101:   }
102: 
103:   private void executeBatchOperation(
104:       final PersistedBatchOperation batchOperation, final TaskResultBuilder taskResultBuilder) {
105:     if (batchOperation.isSuspended()) {
106:       LOG.trace("Batch operation {} is suspended.", batchOperation.getKey());
107:       return;
108:     }
109: 
110:     // First fire a start event
111:     appendStartedCommand(taskResultBuilder, batchOperation);
112: 
113:     try {
114:       // Then append the chunks
115:       final var keys = queryAllKeys(batchOperation);
116: 
117:       if (!keys.isEmpty()) {
118:         LOG.debug(
119:             "Found {} items for batch operation with key {} on partition {}.",
120:             keys.size(),
121:             batchOperation.getKey(),
122:             partitionId);
123:         for (int i = 0; i < keys.size(); i += chunkSize) {
124:           final Set<Item> chunkKeys =
125:               keys.stream().skip(i).limit(chunkSize).collect(Collectors.toSet());
126:           appendChunk(batchOperation.getKey(), taskResultBuilder, chunkKeys);
127:           metrics.recordChunkCreated(batchOperation.getBatchOperationType());
128:         }
129:       } else {
130:         LOG.debug(
131:             "No items found for batch operation with key {} on partition {}.",
132:             batchOperation.getKey(),
133:             partitionId);
134:       }
135: 
136:       metrics.recordItemsPerPartition(
137:           keys.size(), batchOperation.getKey(), batchOperation.getBatchOperationType());
138: 
139:       appendExecution(batchOperation.getKey(), taskResultBuilder);
140: 
141:       metrics.startStartExecuteLatencyMeasure(
142:           batchOperation.getKey(), batchOperation.getBatchOperationType());
143:       metrics.startTotalExecutionDurationMeasure(
144:           batchOperation.getKey(), batchOperation.getBatchOperationType());
145:     } catch (final Exception e) {
146:       LOG.error(
147:           "Failed to append chunks for batch operation with key {}. It will be removed from queue",
148:           batchOperation.getKey(),
149:           e);
150:       appendFailedCommand(taskResultBuilder, batchOperation);
151:     }
152:   }
153: 
154:   private void appendStartedCommand(
155:       final TaskResultBuilder taskResultBuilder, final PersistedBatchOperation batchOperation) {
156:     final var batchOperationKey = batchOperation.getKey();
157:     final var command = new BatchOperationCreationRecord();
158:     command.setBatchOperationKey(batchOperationKey);
159:     command.setBatchOperationType(batchOperation.getBatchOperationType());
160:     LOG.debug("Appending batch operation {} started event", batchOperationKey);
161:     taskResultBuilder.appendCommandRecord(
162:         batchOperationKey,
163:         BatchOperationIntent.START,
164:         command,
165:         FollowUpCommandMetadata.of(b -> b.batchOperationReference(batchOperationKey)));
166:   }
167: 
168:   private void appendFailedCommand(
169:       final TaskResultBuilder taskResultBuilder, final PersistedBatchOperation batchOperation) {
170:     final var batchOperationKey = batchOperation.getKey();
171:     final var command = new BatchOperationCreationRecord();
172:     command.setBatchOperationKey(batchOperationKey);
173:     command.setBatchOperationType(batchOperation.getBatchOperationType());
174:     LOG.debug("Appending batch operation {} failed event", batchOperationKey);
175:     taskResultBuilder.appendCommandRecord(
176:         batchOperationKey,
177:         BatchOperationIntent.FAIL,
178:         command,
179:         FollowUpCommandMetadata.of(b -> b.batchOperationReference(batchOperationKey)));
180:   }
181: 
182:   private void appendChunk(
183:       final Long batchOperationKey,
184:       final TaskResultBuilder taskResultBuilder,
185:       final Set<Item> items) {
186:     final var command = new BatchOperationChunkRecord();
187:     command.setBatchOperationKey(batchOperationKey);
188:     command.setItems(
189:         items.stream()
190:             .map(
191:                 i ->
192:                     new BatchOperationItem()
193:                         .setItemKey(i.itemKey())
194:                         .setProcessInstanceKey(i.processInstanceKey()))
195:             .collect(Collectors.toSet()));
196: 
197:     LOG.debug("Appending batch operation {} chunk with {} items.", batchOperationKey, items.size());
198:     taskResultBuilder.appendCommandRecord(
199:         batchOperationKey,
200:         BatchOperationChunkIntent.CREATE,
201:         command,
202:         FollowUpCommandMetadata.of(b -> b.batchOperationReference(batchOperationKey)));
203:   }
204: 
205:   private void appendExecution(
206:       final Long batchOperationKey, final TaskResultBuilder taskResultBuilder) {
207:     final var command = new BatchOperationExecutionRecord();
208:     command.setBatchOperationKey(batchOperationKey);
209: 
210:     LOG.debug("Appending batch operation execution {}", batchOperationKey);
211:     taskResultBuilder.appendCommandRecord(
212:         batchOperationKey,
213:         BatchOperationExecutionIntent.EXECUTE,
214:         command,
215:         FollowUpCommandMetadata.of(b -> b.batchOperationReference(batchOperationKey)));
216:   }
217: 
218:   private Set<Item> queryAllKeys(final PersistedBatchOperation batchOperation) {
219:     final Supplier<Boolean> abortCondition =
220:         () -> !batchOperationState.exists(batchOperation.getKey());
221: 
222:     try (final var ignored =
223:         metrics.startTotalQueryDurationMeasure(
224:             batchOperation.getKey(), batchOperation.getBatchOperationType())) {
225:       return switch (batchOperation.getBatchOperationType()) {
226:         case CANCEL_PROCESS_INSTANCE ->
227:             entityKeyProvider.fetchProcessInstanceItems(
228:                 partitionId,
229:                 batchOperation.getEntityFilter(ProcessInstanceFilter.class).toBuilder()
230:                     .states(ProcessInstanceState.ACTIVE.name())
231:                     .parentProcessInstanceKeyOperations(Operation.exists(false))
232:                     .build(),
233:                 batchOperation.getAuthentication(),
234:                 abortCondition);
235:         case MIGRATE_PROCESS_INSTANCE, MODIFY_PROCESS_INSTANCE ->
236:             entityKeyProvider.fetchProcessInstanceItems(
237:                 partitionId,
238:                 batchOperation.getEntityFilter(ProcessInstanceFilter.class).toBuilder()
239:                     .states(ProcessInstanceState.ACTIVE.name())
240:                     .build(),
241:                 batchOperation.getAuthentication(),
242:                 abortCondition);
243:         case RESOLVE_INCIDENT ->
244:             entityKeyProvider.fetchIncidentItems(
245:                 partitionId,
246:                 batchOperation.getEntityFilter(ProcessInstanceFilter.class).toBuilder()
247:                     .states(ProcessInstanceState.ACTIVE.name())
248:                     .build(),
249:                 batchOperation.getAuthentication(),
250:                 abortCondition);
251:         default ->
252:             throw new IllegalArgumentException(
253:                 "Unexpected batch operation type: " + batchOperation.getBatchOperationType());
254:       };
255:     } finally {
256:       metrics.stopQueryLatencyMeasure(batchOperation.getKey());
257:     }
258:   }
259: }
